<script>
(function(){
  const boardEl=document.getElementById('board');
  const scoreEl=document.getElementById('score');
  const bestEl=document.getElementById('best');
  const popEl=document.getElementById('scorePop');
  const newGame=document.getElementById('newGame');

  const initial=[
    [0,0,2,0],
    [0,0,0,0],
    [0,2,4,2],
    [0,0,8,2]
  ];

  const scripted=[
    {score:24,board:[
      [0,2,2,4],
      [0,0,4,0],
      [0,0,8,2],
      [0,0,0,0]
    ],pop:'+4'},
    {score:36,board:[
      [0,0,0,0],
      [0,2,2,0],
      [0,0,4,4],
      [0,2,8,2]
    ],pop:''},
    {score:36,board:[
      [2,0,0,0],
      [4,0,0,0],
      [8,0,0,0],
      [2,8,2,0]
    ],pop:'+12'},
    {score:36,board:[
      [2,0,0,2],
      [0,0,0,4],
      [0,0,0,8],
      [0,2,8,2]
    ],pop:''},
    {score:36,board:[
      [0,0,0,0],
      [0,2,2,0],
      [0,0,4,4],
      [0,2,8,2]
    ],pop:''}
  ];

  let state=initial.map(r=>r.slice()), score=20, best=20, moveNo=0;
  let touchStart=null;

  function draw(){
    boardEl.innerHTML='';
    state.flat().forEach(value=>{
      const cell=document.createElement('div');
      cell.className='cell'+(value?' v'+value:'');
      if(value) cell.textContent=value;
      boardEl.appendChild(cell);
    });
    scoreEl.textContent=score;
    bestEl.textContent=best;
  }

  function randomTile(grid){
    const empty=[];
    grid.forEach((r,y)=>r.forEach((v,x)=>{if(!v)empty.push([y,x])}));
    if(!empty.length)return;
    const [y,x]=empty[Math.floor(Math.random()*empty.length)];
    grid[y][x]=Math.random()<.9?2:4;
  }

  function rotate(g){return g[0].map((_,i)=>g.map(r=>r[i]).reverse())}
  function slideRow(row){
    let a=row.filter(Boolean), gained=0;
    for(let i=0;i<a.length-1;i++){
      if(a[i]===a[i+1]){a[i]*=2;gained+=a[i];a.splice(i+1,1)}
    }
    while(a.length<4)a.push(0);
    return {row:a,gained};
  }
  function move(dir){
    if(moveNo<scripted.length){
      const s=scripted[moveNo++];
      state=s.board.map(r=>r.slice()); score=s.score; best=Math.max(best,score);
      popEl.textContent=s.pop||'';
      draw();
      setTimeout(()=>popEl.textContent='',700);
      return;
    }
    let g=state.map(r=>r.slice()), turns=0;
    if(dir==='up')turns=1;
    if(dir==='right')turns=2;
    if(dir==='down')turns=3;
    for(let i=0;i<turns;i++)g=rotate(g);
    let gained=0;
    g=g.map(row=>{const x=slideRow(row);gained+=x.gained;return x.row});
    for(let i=0;i<(4-turns)%4;i++)g=rotate(g);
    if(JSON.stringify(g)!==JSON.stringify(state)){
      state=g; score+=gained; best=Math.max(best,score);
      if(gained)popEl.textContent='+'+gained;
      randomTile(state); draw();
      setTimeout(()=>popEl.textContent='',700);
    }
  }
  function reset(){
    state=initial.map(r=>r.slice());score=20;moveNo=0;popEl.textContent='';draw();
  }
  function keyHandler(e){
    const k=e.key.toLowerCase();
    const map={arrowup:'up',w:'up',arrowdown:'down',s:'down',arrowleft:'left',a:'left',arrowright:'right',d:'right'};
    if(map[k]){e.preventDefault();move(map[k])}
  }
  document.addEventListener('keydown',keyHandler);
  newGame.addEventListener('click',reset);
  document.getElementById('classicBtn').addEventListener('click',()=>{reset();document.getElementById('classicBtn').classList.add('active');document.getElementById('cupcakeBtn').classList.remove('active')});
  document.getElementById('cupcakeBtn').addEventListener('click',()=>{document.getElementById('cupcakeBtn').classList.add('active');document.getElementById('classicBtn').classList.remove('active')});

  boardEl.addEventListener('touchstart',e=>{const t=e.changedTouches[0];touchStart=[t.clientX,t.clientY]},{passive:true});
  boardEl.addEventListener('touchend',e=>{
    if(!touchStart)return;
    const t=e.changedTouches[0],dx=t.clientX-touchStart[0],dy=t.clientY-touchStart[1];
    if(Math.max(Math.abs(dx),Math.abs(dy))>25)move(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'));
    touchStart=null;
  },{passive:true});
  draw();
})();
</script>
</body>
</html>
